1	/**
2	 * @file
3	 * @copyright SPDX-License-Identifier: Apache-2.0
4	 *
5	 * @test @b mrn_rmw_fwd
6	 * @test @b mrn_rmw_l1d
7	 * @parblock
8	 * Load-pathway subdivision probe for core-179 SDC.
9	 *
10	 * Context: we already localized the 179 SDC to the per-core load data path
11	 * (L1D read array -> load port) via movbe_l1d_vs_l2 (see memory
12	 * l1d-read-path-sdc-confirmed).  This probe narrows it further by
13	 * distinguishing two load sub-paths that both reach the load port:
14	 *
15	 *   - store buffer FORWARDING: a load from an address that was just stored
16	 *     (str then ldr, same address) can be satisfied directly from the store
17	 *     buffer WITHOUT going through the L1D read array.
18	 *   - L1D ARRAY read: a load from an address already resident in the L1D
19	 *     array (not just written) is served by the L1D read array -> load port.
20	 *
21	 * mrn_rmw (original) does `str res->temp[i]; dst[i]=ldr temp[i]` — the ldr
22	 * of temp[i] immediately follows the str of temp[i] at the same address,
23	 * so it exercises store-buffer FORWARDING.  mrn_rmw is known to trigger the
24	 * 179 SDC.  Question: does the SDC also occur when the same reload is forced
25	 * to go through the L1D ARRAY read instead of forwarding?
26	 *
27	 * Two SEPARATE tests (no shared run with a regime conditional — that
28	 * conditional perturbs the hot loop and silences the timing-sensitive
29	 * defect; see memory dump-variant-noremove-report-fail-verified):
30	 *
31	 *   - mrn_rmw_fwd: hot loop byte-identical to mrn_rmw.cpp.  The
32	 *     `store_qword(&temp[i],res); store_qword(&dst[i], load_qword(&temp[i]))`
33	 *     pair keeps the str->ldr-same-address forwarding path.  Expected:
34	 *     SDC triggers (baseline, matches mrn_rmw).
35	 *   - mrn_rmw_l1d: same hot loop, but `dc civac`+dsb is inserted between the
36	 *     str to temp[i] and the ldr of temp[i], evicting/flushing the store so
37	 *     the ldr must be served from the L1D array (or further) rather than
38	 *     from store-buffer forwarding.  If the SDC disappears here while
39	 *     mrn_rmw_fwd still triggers, the defect is in the store-buffer
40	 *     FORWARDING path; if it persists, the common point is downstream
41	 *     (load port -> register), since both sub-paths converge there.
42	 *
43	 * On miscompare, logs inputA/inputB/golden/actual/xor (same as mrn_rmw_dump)
44	 * then report_fail_msg (noreturn) — matching mrn_rmw's behavior; one pass
45	 * over MRN_RMW_COUNT already logs a batch of events before thread exit.
46	 * @endparblock
47	 */
48	
49	#include "sandstone.h"
50	#include <cstdint>
51	#include <cstring>
52	
53	#define MRN_RMW_COUNT 1024
54	
55	struct MrnRmwData {
56	    uint64_t *srcA;
57	    uint64_t *srcB;
58	    uint64_t *expected;
59	};
60	
61	#if defined(__aarch64__)
62	static inline void store_qword(void *addr, uint64_t val) {
63	    __asm__ volatile ("str %1, [%0]" : : "r"(addr), "r"(val) : "memory");
64	}
65	static inline uint64_t load_qword(const void *addr) {
66	    uint64_t res;
67	    __asm__ volatile ("ldr %0, [%1]" : "=r"(res) : "r"(addr) : "memory");
68	    return res;
69	}
70	static inline void evict_l1d_line(const void *addr) {
71	    __asm__ volatile(
72	        "dc civac, %0\n\t"
73	        "dsb sy\n\t"
74	        :: "r"(addr) : "memory"
75	    );
76	}
77	#endif
78	
79	static int mrn_rmw_probe_init(struct test *test) {
80	    auto *data = static_cast<MrnRmwData *>(malloc(sizeof(MrnRmwData)));
81	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
82	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
83	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
84	
85	    memset_random(data->srcA, MRN_RMW_COUNT * sizeof(uint64_t));
86	    memset_random(data->srcB, MRN_RMW_COUNT * sizeof(uint64_t));
87	
88	    for (int i = 0; i < MRN_RMW_COUNT; i++) {
89	        switch (i % 4) {
90	            case 0: data->expected[i] = data->srcA[i] + data->srcB[i]; break;
91	            case 1: data->expected[i] = data->srcA[i] - data->srcB[i]; break;
92	            case 2: data->expected[i] = data->srcA[i] ^ data->srcB[i]; break;
93	            case 3: data->expected[i] = data->srcA[i] & data->srcB[i]; break;
94	        }
95	    }
96	
97	    test->data = data;
98	    return EXIT_SUCCESS;
99	}
100	
101	static int mrn_rmw_probe_cleanup(struct test *test) {
102	    auto *data = static_cast<MrnRmwData *>(test->data);
103	    if (data) {
104	        free(data->srcA);
105	        free(data->srcB);
106	        free(data->expected);
107	        free(data);
108	    }
109	    return EXIT_SUCCESS;
110	}
111	
112	// Shared miscompare logger (cold branch only).
113	static void log_miscompare(const char *tag, int i, const char *op,
114	                           uint64_t inputA, uint64_t inputB,
115	                           uint64_t golden, uint64_t actual)
116	{
117	    uint64_t xorv = golden ^ actual;
118	    unsigned char *gb = (unsigned char *)&golden;
119	    unsigned char *ab = (unsigned char *)&actual;
120	    unsigned char *xb = (unsigned char *)&xorv;
121	    log_error("%s: miscompare at index %u (op=%s): "
122	              "inputA=0x%016lX inputB=0x%016lX golden=0x%016lX "
123	              "actual=0x%016lX xor=0x%016lX | "
124	              "bytes[b7..b0] golden=%02X%02X%02X%02X%02X%02X%02X%02X "
125	              "actual=%02X%02X%02X%02X%02X%02X%02X%02X "
126	              "xor=%02X%02X%02X%02X%02X%02X%02X%02X",
127	              tag, (unsigned)i, op,
128	              (unsigned long)inputA, (unsigned long)inputB,
129	              (unsigned long)golden, (unsigned long)actual,
130	              (unsigned long)xorv,
131	              gb[7], gb[6], gb[5], gb[4], gb[3], gb[2], gb[1], gb[0],
132	              ab[7], ab[6], ab[5], ab[4], ab[3], ab[2], ab[1], ab[0],
133	              xb[7], xb[6], xb[5], xb[4], xb[3], xb[2], xb[1], xb[0]);
134	    report_fail_msg("%s: data miscompare at index %u (op=%s)", tag, (unsigned)i, op);
135	}
136	
137	// ---------------------------------------------------------------------------
138	// mrn_rmw_fwd: store-buffer FORWARDING path.  Hot loop byte-identical to
139	// mrn_rmw.cpp — str to temp[i] immediately followed by ldr of temp[i] at the
140	// same address, served by store-buffer forwarding.
141	// ---------------------------------------------------------------------------
142	static int mrn_rmw_fwd_run(struct test *test, int cpu) {
143	    (void)cpu;
144	    auto *data = static_cast<MrnRmwData *>(test->data);
145	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
146	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
147	
148	    TEST_LOOP(test, 1 << 13) {
149	        for (int i = 0; i < MRN_RMW_COUNT; i++) {
150	            uint64_t a = data->srcA[i];
151	            uint64_t b = data->srcB[i];
152	            uint64_t res;
153	            switch (i % 4) {
154	                case 0: res = a + b; break;
155	                case 1: res = a - b; break;
156	                case 2: res = a ^ b; break;
157	                default: res = a & b; break;
158	            }
159	
160	            store_qword(&temp[i], res);
161	            store_qword(&dst[i], load_qword(&temp[i]));
162	        }
163	
164	        if (memcmp(dst, data->expected, MRN_RMW_COUNT * sizeof(uint64_t)) != 0) {
165	            for (int i = 0; i < MRN_RMW_COUNT; i++) {
166	                if (dst[i] != data->expected[i]) {
167	                    const char *op = (i % 4 == 0) ? "add"
168	                                   : (i % 4 == 1) ? "sub"
169	                                   : (i % 4 == 2) ? "xor" : "and";
170	                    log_miscompare("mrn_rmw_fwd", i, op,
171	                                   data->srcA[i], data->srcB[i],
172	                                   data->expected[i], dst[i]);
173	                }
174	            }
175	        }
176	    }
177	
178	    free(dst);
179	    free(temp);
180	    return EXIT_SUCCESS;
181	}
182	
183	// ---------------------------------------------------------------------------
184	// mrn_rmw_l1d: L1D-ARRAY read path.  Same hot loop, but `dc civac`+dsb is
185	// inserted between the str to temp[i] and the ldr of temp[i].  This flushes
186	// the just-stored line out of the store buffer / L1D so the subsequent ldr
187	// is served from the L1D array (or further) instead of store-buffer
188	// forwarding.  The str/ldr/ALU sequence around it is otherwise identical.
189	// ---------------------------------------------------------------------------
190	static int mrn_rmw_l1d_run(struct test *test, int cpu) {
191	    (void)cpu;
192	    auto *data = static_cast<MrnRmwData *>(test->data);
193	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
194	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_COUNT * sizeof(uint64_t)));
195	
196	    TEST_LOOP(test, 1 << 13) {
197	        for (int i = 0; i < MRN_RMW_COUNT; i++) {
198	            uint64_t a = data->srcA[i];
199	            uint64_t b = data->srcB[i];
200	            uint64_t res;
201	            switch (i % 4) {
202	                case 0: res = a + b; break;
203	                case 1: res = a - b; break;
204	                case 2: res = a ^ b; break;
205	                default: res = a & b; break;
206	            }
207	
208	            store_qword(&temp[i], res);
209	            // Flush the just-stored line so the reload below is served from
210	            // the L1D array / further, NOT from store-buffer forwarding.
211	            evict_l1d_line(&temp[i]);
212	            store_qword(&dst[i], load_qword(&temp[i]));
213	        }
214	
215	        if (memcmp(dst, data->expected, MRN_RMW_COUNT * sizeof(uint64_t)) != 0) {
216	            for (int i = 0; i < MRN_RMW_COUNT; i++) {
217	                if (dst[i] != data->expected[i]) {
218	                    const char *op = (i % 4 == 0) ? "add"
219	                                   : (i % 4 == 1) ? "sub"
220	                                   : (i % 4 == 2) ? "xor" : "and";
221	                    log_miscompare("mrn_rmw_l1d", i, op,
222	                                   data->srcA[i], data->srcB[i],
223	                                   data->expected[i], dst[i]);
224	                }
225	            }
226	        }
227	    }
228	
229	    free(dst);
230	    free(temp);
231	    return EXIT_SUCCESS;
232	}
233	
234	DECLARE_TEST(mrn_rmw_fwd, "mrn_rmw load-path probe (store-buffer FORWARDING): str then ldr same addr — core-179 SDC expected")
235	    .test_init = mrn_rmw_probe_init,
236	    .test_run = mrn_rmw_fwd_run,
237	    .test_cleanup = mrn_rmw_probe_cleanup,
238	    .quality_level = TEST_QUALITY_PROD,
239	END_DECLARE_TEST
240	
