22	// load_qword_delayed: reload after N data-independent ALU no-ops (mov x9,x9).
23	// Pure timing delay: touches NO memory and NO cache, so the reload still
24	// goes through store-buffer FORWARDING (the stored line is still in the
25	// store buffer; nothing evicted it). Only the str->ldr time gap widened.
26	// Uses .rept N to emit N no-ops compactly.
27	//
28	// Bisection of the timing window: 64 no-ops (~20+ cycles) gave 0 fail / 364
29	// iters; 1 no-op (~1 cycle) gave 1 fail / 10min (mrn_rmw_nop1_10m.log).
30	// So the race window is between 1 and 64 cycles. 2 no-ops (~2 cycles) bisects
31	// the low end: does the residual fail at 1 cycle disappear at 2, or does the
32	// window extend further?  Store buffer cannot drain in 2 cycles, so ldr is
33	// STILL served by forwarding -> path identical to fwd/nop1, only timing changes.
34	static inline uint64_t load_qword_delayed(const void *addr) {
35	    uint64_t res;
36	    __asm__ volatile(
37	        ".rept 2\n\t"
38	        "mov x9, x9\n\t"
39	        ".endr\n\t"
40	        "ldr %0, [%1]"
41	        : "=r"(res) : "r"(addr) : "memory"
42	    );
43	    return res;
44	}
